SELECT ?segment ?pctIncrease WHERE {
  {
    SELECT ?segment (SUM(?c2012) AS ?sum2012) (SUM(?c2013) AS ?sum2013) WHERE {
      ?ym a <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Yearmonth> ;
          <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Yearmonth/customerid> ?cid ;
          <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Yearmonth/date> ?date ;
          <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Yearmonth/consumption> ?consumption .
      ?cust a <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Customer> ;
            <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Customer/customerid> ?cid ;
            <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Customer/segment> ?segment ;
            <http://bird-bird_debit_card_specializing-ontology-20260809-233203/ontology/vkg-bird_debit_card_specializing/Customer/currency> ?currency .
      FILTER(?currency = "EUR")
      BIND(SUBSTR(STR(?date),1,4) AS ?year)
      BIND(IF(?year = "2012", xsd:decimal(?consumption), 0) AS ?c2012)
      BIND(IF(?year = "2013", xsd:decimal(?consumption), 0) AS ?c2013)
    }
    GROUP BY ?segment
  }
  BIND(((?sum2013 - ?sum2012) / ?sum2012) * 100 AS ?pctIncrease)
}
ORDER BY DESC(?pctIncrease)

